function renderCoverageLegend(){const legend=document.querySelector('.coverage-legend');if(!legend)return;legend.replaceChildren();const unknown=['repeating-linear-gradient(135deg,#a7afb0 0 3px,#d8dddc 3px 6px)','Unknown terrain'],unresolved=['repeating-linear-gradient(135deg,#9476b7 0 3px,#ddd5e7 3px 6px)','Unresolved profile limit'],outside=['repeating-linear-gradient(135deg,#f7f8f7 0 3px,#d9dfdc 3px 6px)','Outside requested area'];let items;if(coverageSettings.mode==='overlap')items=[['#f0ca62','1 usable router'],['#61a88c','2 usable routers'],['#287b64','3+ usable routers'],['#ce796d','No usable link'],unknown,unresolved,outside];else if(coverageSettings.mode==='best_source'){items=((coverageDisplayInfo||coverageJob)?.source_ids||[]).slice(0,8).map(id=>[servingColor(id),id]);items.push(['#ce796d','No usable link'],unknown,unresolved,outside);}else items=[['#287b64','≥ 10 dB'],['#61a88c','5–10 dB'],['#f0ca62','0–5 dB'],['#ce796d','Not usable'],unknown,unresolved,outside];for(const [color,label] of items){const span=document.createElement('span'),swatch=document.createElement('i');swatch.style.background=color;span.append(swatch,document.createTextNode(label));legend.append(span);}}
function renderCoverageSources(){const list=$('coverage-sources');if(!list)return;list.replaceChildren();const sources=(result?.route||[]).filter(site=>!['endpoint_a','endpoint_b','client'].includes(site.kind));if(!result?.search_complete||!sources.length){const message=document.createElement('p');message.className='hint';message.textContent='Run a completed route search to choose repeater sources.';list.append(message);$('coverage-source-count').textContent='No selected route';return;}const validIds=new Set(sources.map(site=>site.id));if(coverageSettings.source_ids.some(id=>!validIds.has(id))){coverageSettings.source_ids=[];recordEdit();}const allSelected=coverageSettings.source_ids.length===0,selectedCount=allSelected?sources.length:coverageSettings.source_ids.length;$('coverage-source-count').textContent=allSelected?`${sources.length} available`:`${selectedCount} selected of ${sources.length}`;for(const site of sources){const label=document.createElement('label');label.className='coverage-source';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=allSelected||coverageSettings.source_ids.includes(site.id);checkbox.disabled=busy||coverageBusy;checkbox.dataset.sourceId=site.id;checkbox.onchange=updateCoverageSourceSelection;const name=document.createElement('span');name.textContent=`${site.id} · ${site.origin==='known'?'existing':'proposed'}`;label.append(checkbox,name);list.append(label);}}
