function applyCoverageHeightScenario(){const edits=new Map();for(const input of document.querySelectorAll('[data-height-source]')){const height=Number(input.value),original=Number(input.dataset.originalHeight);if(!Number.isFinite(height)||height<.1||height>500){$('coverage-compare-summary').textContent='Plan antenna heights must be between 0.1 and 500 m AGL.';return;}if(Math.abs(height-original)>.0001)edits.set(input.dataset.heightSource,height);}if(!edits.size)return;for(const [siteId,height] of edits){const existing=meshcoreRouters.find(router=>router.id===siteId);if(existing){existing.antenna_height_m=height;existing.height_override=true;continue;}const manual=manualRouters.find(router=>router.id===siteId);if(manual){manual.antenna_height_m=height;manual.policy='required';continue;}const site=(result?.route||[]).find(item=>item.id===siteId);if(site)manualRouters.push({id:'M-'+crypto.randomUUID(),latitude:site.latitude,longitude:site.longitude,antenna_height_m:height,policy:'required'});}coverageHeightOverrides={};renderManualRouters();renderMeshcoreRouters();recordEdit();invalidate();scheduleCoverageCheck();$('coverage-compare-summary').textContent='Scenario heights are now explicit plan edits. Required proposed sites were pinned; use Undo to restore the previous plan.';}
