(async()=>{try{const data=await refresh();rf=data.rf;candidates=data.candidates;baseRf=clone(rf);baseCandidates=clone(candidates);if(data.plan)load(data.plan);else{buildSettings();syncTerrainControls();syncCoverageInputs();renderManualRouters();}renderCoverageLegend();renderCoverageSources();renderFailureControls();renderHeightScenarioControls();lastHistoryPlan=clone(plan());undoStack=[];redoStack=[];setHistoryButtons();if(data.job.terrain_estimate&&['queued','preparing'].includes(data.job.state)){activeJobId=data.job.job_id;preparingTerrain=true;setBusy(true);pollTerrainJob();}else if(['queued','running'].includes(data.job.state)){activeJobId=data.job.job_id;lastSnapshotVersion=0;jobStartedAt=(data.job.started_at||Date.now()/1000)*1000;setBusy(true);poll();}if(data.projects.previous_result||data.job.state==='interrupted')showPlanSummary(data);if(data.coverage_job){coverageJob=data.coverage_job;const active=['queued','running'].includes(coverageJob.state);coverageBusyState(active);$('coverage-cancel').hidden=!active;coverageCursor=0;pollCoverage(coverageJob.job_id);}if(terrainLoaded)updateTerrainCoverage();await refreshCoverageRunSelectors();}catch(e){status(e.message,true);}})();
